const data = $getWorkflowStaticData('global');
if (!data.refresh_token || !data.location_id) {
  throw new Error('Faltan staticData.global.refresh_token o location_id. ZeroManual los inyecta al activar.');
}
return [{
  json: {
    refresh_token: data.refresh_token,
    location_id: data.location_id,
    client_name: data.client_name || '',
    business_id: data.business_id || ''
  }
}];

const reviews = ($input.first().json.reviews) || [];
return reviews
  .filter((review) => !(review.reviewReply && review.reviewReply.comment))
  .map((review) => ({ json: review }));

const review = $input.item.json || {};
const reviewer = review.reviewer || {};
return [{
  json: {
    review_name: review.name || '',
    reviewer_name: reviewer.displayName || 'Anónimo',
    starRating: review.starRating || '',
    review_text: review.comment || ''
  }
}];

const data = $getWorkflowStaticData('global');
const seen = new Set(Array.isArray(data.drafted_review_ids) ? data.drafted_review_ids : []);
return $input.all().filter((item) => {
  const id = item.json && item.json.review_name;
  return Boolean(id) && !seen.has(id);
});

const review = $('Normalize Review').item.json;
const llm = $input.item.json || {};
const choice = llm.choices && llm.choices[0] && llm.choices[0].message && llm.choices[0].message.content;
const content = (llm.message && llm.message.content) || choice || '';
return [{
  json: {
    review_name: review.review_name,
    reviewer_name: review.reviewer_name,
    starRating: review.starRating,
    review_text: review.review_text,
    message: { content: content },
    choices: [{ message: { content: content } }]
  }
}];

const data = $getWorkflowStaticData('global');
const seen = Array.isArray(data.drafted_review_ids) ? data.drafted_review_ids.slice() : [];
for (const item of $input.all()) {
  const id = item.json && item.json.review_name;
  if (id && seen.indexOf(id) === -1) seen.push(id);
}
data.drafted_review_ids = seen.slice(-400);
return $input.all();

if (typeof fetch !== 'function') {
  throw new Error('Post Reply to Google necesita fetch en el nodo Code (Node 18+).');
}
const data = $getWorkflowStaticData('global');
const clientId = $env.ZEROMANUAL_GOOGLE_CLIENT_ID;
const clientSecret = $env.ZEROMANUAL_GOOGLE_CLIENT_SECRET;
if (!data.refresh_token || !clientId || !clientSecret) {
  throw new Error('Faltan staticData.global.refresh_token o ZEROMANUAL_GOOGLE_CLIENT_ID/SECRET en n8n.');
}
const tokenRes = await fetch('https://oauth2.googleapis.com/token', {
  method: 'POST',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: new URLSearchParams({
    client_id: clientId,
    client_secret: clientSecret,
    refresh_token: data.refresh_token,
    grant_type: 'refresh_token'
  })
});
if (!tokenRes.ok) {
  throw new Error('Token Google: ' + (await tokenRes.text()));
}
const token = await tokenRes.json();
const item = ($input.first() && $input.first().json) || {};
const body = item.body && typeof item.body === 'object' ? item.body : item;
const reply = body.final_reply || '';
let reviewName = String(body.review_id || '');
if (!reply || !reviewName) {
  throw new Error('El webhook debe enviar review_id y final_reply.');
}
if (!reviewName.startsWith('accounts/')) {
  const loc = String(data.location_id || '').replace(/\/$/, '');
  reviewName = loc + '/reviews/' + reviewName.replace(/^\//, '');
}
const url = 'https://mybusiness.googleapis.com/v4/' + reviewName + '/reply';
const putRes = await fetch(url, {
  method: 'PUT',
  headers: {
    Authorization: 'Bearer ' + token.access_token,
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({ comment: reply })
});
const raw = await putRes.text();
if (!putRes.ok) {
  throw new Error('Reply Google: ' + raw);
}
let google = {};
try { google = JSON.parse(raw); } catch (err) { google = { raw: raw }; }
return [{ json: { ok: true, review_name: reviewName, google: google } }];
